// Packs the S1000D omni-complete dictionaries of the reference repository
//   https://github.com/Pratham1910/vim-s1000d-omnicomplete  (vim/autoload/xml/S1000D_<issue>_<schema>.vim)
// into ONE compact gzip JSON the verification tests read. The dictionaries were generated by the repository's
// xsd2omni.xsl from the official S1000D XSDs, i.e. by a different toolchain than our grammar compiler, which makes
// them an independent cross-check (NOT a replacement for the XSDs: they carry no ordering or occurrence).
//
//   node scripts/import-vim-dicts.mjs <dir with the .vim files>
// Output: frontend/src/studio/__tests__/verify/data/vim-s1000d.json.gz   { "<issue>/<schema>": { element: { c:[children], a:{attr:[values]} } } }
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const dir = process.argv[2];
if (!dir) { console.error('usage: node scripts/import-vim-dicts.mjs <dir>'); process.exit(1); }
const ISSUES = { '42': '4-2', '50': '5-0', '6': '6', '7': '7' };
const q = /'((?:[^']|'')*)'/g;
const strs = (s) => [...s.matchAll(q)].map((m) => m[1].replace(/''/g, "'"));
const out = {};
let files = 0;
for (const f of fs.readdirSync(dir)) {
  const m = /^S1000D_(\d+)_([a-z]+)\.vim$/.exec(f);
  if (!m || !ISSUES[m[1]]) continue;
  const dict = {};
  for (const line of fs.readFileSync(path.join(dir, f), 'utf8').split('\n')) {
    const r = /^\\ '([^']+)': \[\[(.*?)\], \{(.*)\}\],?\s*$/.exec(line);
    if (!r) continue;
    const attrs = {};
    const ar = /'([^']+)': \[((?:'(?:[^']|'')*'(?:, )?)*)\]/g;
    let a;
    while ((a = ar.exec(r[3]))) attrs[a[1]] = strs(a[2]);
    dict[r[1]] = { c: strs(r[2]), a: attrs };
  }
  out[`${ISSUES[m[1]]}/${m[2]}`] = dict;
  files++;
}
const dest = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'frontend/src/studio/__tests__/verify/data/vim-s1000d.json.gz');
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, zlib.gzipSync(JSON.stringify(out), { level: 9 }));
console.log(`${files} dictionaries -> ${dest} (${(fs.statSync(dest).size / 1024).toFixed(0)} KB)`);
